if (ctx.expected_impact != null && !(ctx.expected_impact instanceof Map)) { ctx.expected_impact = new HashMap(); }
if (ctx.evidence != null && !(ctx.evidence instanceof List)) { ctx.evidence = new ArrayList(); }
if (ctx.details != null && !(ctx.details instanceof Map)) { ctx.remove('details'); }

List errs = new ArrayList();
String type = ctx.type instanceof String ? (String) ctx.type : null;
List analystTypes = ['capability_gap','rule_tuning','rule_authoring'];
if (type == null || type.isEmpty()) {
  errs.add('missing_top_level:type');
} else if (analystTypes.contains(type)) {
  // Informational/analyst-facing — minimal validation so these show up in the
  // Autonomy Feed UI. The applier filters on type=mutation_intent so these
  // never trip the governance cascade.
  String[] requiredAnalyst = new String[] {'rec_id','source','status','title'};
  for (String f : requiredAnalyst) {
    if (ctx.get(f) == null) { errs.add('missing_top_level:' + f); continue; }
    if (ctx.get(f) instanceof String && ((String) ctx.get(f)).isEmpty()) { errs.add('empty_top_level:' + f); }
  }
} else if (!type.equals('mutation_intent')) {
  errs.add('type_not_allowed:' + type);
} else {
  String[] requiredTop = new String[] {'rec_id','schema_version','source','status','title','summary','confidence','track','details'};
  for (String f : requiredTop) {
    if (ctx.get(f) == null) { errs.add('missing_top_level:' + f); continue; }
    if (ctx.get(f) instanceof String && ((String) ctx.get(f)).isEmpty()) { errs.add('empty_top_level:' + f); }
  }
  if (ctx.track instanceof String) {
    String tr = (String) ctx.track;
    if (!tr.equals('deterministic') && !tr.equals('agentic')) { errs.add('track_invalid:' + tr); }
  }
  if (ctx.confidence != null && ctx.confidence instanceof Number) {
    double cf = ((Number) ctx.confidence).doubleValue();
    if (cf < 0 || cf > 100) { errs.add('confidence_out_of_range:' + cf); }
  }
  if (ctx.status instanceof String) {
    String st = (String) ctx.status;
    List allowedStatuses = ['pending','pending_backtest','auto_apply_ready','pending_review','applying','applied','rolled_back','failed','rejected','rejected_backtest','rejected_drift','rejected_budget','rejected_killswitch','rejected_freeze','rejected_ownership','rejected_loop','rejected_trust','approved_by_human','rejected_by_human','approved','auto-applied','auto-rejected'];
    if (!allowedStatuses.contains(st)) { errs.add('status_invalid:' + st); }
  }
  if (ctx.details instanceof Map) {
    Map details = (Map) ctx.details;
    String[] reqDetails = new String[] {'artifact_type','artifact_id','op','expected_ownership','reason'};
    for (String f : reqDetails) {
      if (details.get(f) == null) { errs.add('missing_details:' + f); continue; }
      if (details.get(f) instanceof String && ((String) details.get(f)).isEmpty()) { errs.add('empty_details:' + f); }
    }
    List allowedArtifactTypes = ['agent','skill','workflow','rule','exception'];
    if (details.artifact_type instanceof String && !allowedArtifactTypes.contains(details.artifact_type)) {
      errs.add('artifact_type_invalid:' + details.artifact_type);
    }
    List allowedOps = ['create','update','delete','enable','disable'];
    if (details.op instanceof String && !allowedOps.contains(details.op)) {
      errs.add('op_invalid:' + details.op);
    }
    List allowedOwners = ['autosoc','canonical','platform'];
    if (details.expected_ownership instanceof String && !allowedOwners.contains(details.expected_ownership)) {
      errs.add('expected_ownership_invalid:' + details.expected_ownership);
    }
    if (details.reason instanceof String && ((String) details.reason).length() < 20) {
      errs.add('reason_too_short:len=' + ((String) details.reason).length());
    }
    String op = details.op instanceof String ? (String) details.op : null;
    String at = details.artifact_type instanceof String ? (String) details.artifact_type : null;
    if (op != null && (op.equals('create') || op.equals('update'))) {
      if (details.get('new_definition') == null && details.get('patch') == null) {
        errs.add('missing_payload_for_' + op + ':new_definition_or_patch_required');
      }
    }
    if ('rule'.equals(at) && 'update'.equals(op)) {
      if (!(details.patch instanceof Map)) {
        errs.add('rule_update_requires_structured_patch:patch_missing_or_not_object');
      } else {
        Map patch = (Map) details.patch;
        String[] reqPatch = new String[] {'rule_id','action','patch_fields','current_values','impact_prediction'};
        for (String f : reqPatch) {
          if (patch.get(f) == null) { errs.add('rule_patch_missing:' + f); }
        }
        if (patch.action instanceof String) {
          List allowedActions = ['raise_threshold','lower_threshold','tighten_query','broaden_query','enable','disable','add_note','change_severity','change_risk_score'];
          if (!allowedActions.contains(patch.action)) {
            errs.add('rule_patch_action_invalid:' + patch.action);
          }
        }
        if (patch.patch_fields != null && !(patch.patch_fields instanceof Map)) {
          errs.add('rule_patch_fields_not_object');
        } else if (patch.patch_fields instanceof Map && ((Map) patch.patch_fields).isEmpty()) {
          errs.add('rule_patch_fields_empty');
        }
        if (patch.current_values != null && !(patch.current_values instanceof Map)) {
          errs.add('rule_patch_current_values_not_object');
        }
        if (patch.impact_prediction instanceof Map) {
          Map ip = (Map) patch.impact_prediction;
          if (ip.get('expected_fp_reduction_pct') == null) { errs.add('rule_patch_impact_missing:expected_fp_reduction_pct'); }
          if (ip.get('expected_tp_impact') == null) { errs.add('rule_patch_impact_missing:expected_tp_impact'); }
        } else if (patch.impact_prediction != null) {
          errs.add('rule_patch_impact_not_object');
        }
      }
    }
  }
  boolean hk = ctx.housekeeping != null && ctx.housekeeping instanceof Boolean && ((Boolean) ctx.housekeeping).booleanValue();
  if (!hk) {
    List ev = ctx.evidence instanceof List ? (List) ctx.evidence : null;
    if (ev == null || ev.isEmpty()) { errs.add('evidence_empty'); }
    if (ctx.expected_impact == null) { errs.add('expected_impact_missing'); }
  }
}
if (!errs.isEmpty()) {
  ctx._envelope_errors = errs;
}

List errs = (List) ctx._envelope_errors;
Map orig = new HashMap();
for (entry in ctx.entrySet()) {
  String k = entry.getKey();
  if (k.startsWith('_')) { continue; }
  if (k.equals('@timestamp')) { continue; }
  orig.put(k, entry.getValue());
}
List removeKeys = new ArrayList();
for (String k : ctx.keySet()) {
  if (k.startsWith('_')) { continue; }
  if (k.equals('@timestamp')) { continue; }
  removeKeys.add(k);
}
for (String k : removeKeys) { ctx.remove(k); }
ctx.remove('_envelope_errors');
ctx.source = 'soc-mutation-intent-envelope-validator';
ctx.error = 'envelope_validation_failed: ' + String.join('; ', errs);
ctx.validation_errors = errs;
ctx.rec_id = orig.get('rec_id') != null ? orig.get('rec_id') : '<missing>';
ctx.original_type = orig.get('type') != null ? orig.get('type') : '<missing>';
ctx.original_doc = orig;

String type = ctx.type instanceof String ? (String) ctx.type : null;
Map details = ctx.details instanceof Map ? (Map) ctx.details : null;
boolean isMutationIntent = 'mutation_intent'.equals(type);
boolean hasActionPayload = details != null && (details.get('patch') != null || details.get('new_definition') != null);
if (!isMutationIntent || !hasActionPayload) {
  ctx.final_status = 'no_action';
  ctx._rejection_reason = 'agent_findings_report_no_action_payload';
  ctx._auto_stamped_at = ctx['@timestamp'];
  if (ctx.details == null) { ctx.details = new HashMap(); }
  if (ctx.details instanceof Map) { ((Map) ctx.details).put('action', 'no_action'); }
}
